import java.util.Arrays;
import java.util.List;

public class SolutionTest {
    public static void main(String[] args) {
        Solution.Member member = new Solution.Member("  Alice  ");
        Solution.Trainee trainee = new Solution.Trainee(" Bob\t", "  Institute A ");
        Solution.ResidentTrainee resident =
                new Solution.ResidentTrainee(" Carol ", " Institute B ", " Workshop C ");

        assertEquals("Alice", member.getLabel(), "member label");
        assertEquals("Member[label=Alice]", member.toString(), "member string");
        assertEquals("Bob", trainee.getLabel(), "trainee label");
        assertEquals("Institute A", trainee.getInstitute(), "trainee institute");
        assertEquals("Trainee[label=Bob, institute=Institute A]", trainee.toString(), "trainee string");
        assertEquals("Carol", resident.getLabel(), "resident label");
        assertEquals("Institute B", resident.getInstitute(), "resident institute");
        assertEquals("Workshop C", resident.getWorkshop(), "resident workshop");
        assertEquals("ResidentTrainee[label=Carol, institute=Institute B, workshop=Workshop C]",
                resident.toString(), "resident string");
        assertTrue(trainee instanceof Solution.Member, "Trainee hierarchy");
        assertTrue(resident instanceof Solution.Trainee, "ResidentTrainee hierarchy");

        Solution.Member[] members = {member, trainee, resident};
        List<String> roster = Solution.renderRoster(members);
        assertEquals(Arrays.asList(
                "Member[label=Alice]",
                "Trainee[label=Bob, institute=Institute A]",
                "ResidentTrainee[label=Carol, institute=Institute B, workshop=Workshop C]"),
                roster, "roster order");
        members[0] = new Solution.Member("Changed");
        assertEquals("Member[label=Alice]", roster.get(0), "roster snapshot");
        expectUnsupported(() -> roster.add("x"), "roster unmodifiable");
        assertTrue(Solution.renderRoster(new Solution.Member[0]).isEmpty(), "empty roster");

        expectIllegalArgument(() -> new Solution.Member(null), "null label");
        expectIllegalArgument(() -> new Solution.Member(" \t "), "blank label");
        expectIllegalArgument(() -> new Solution.Trainee("A", null), "null institute");
        expectIllegalArgument(() -> new Solution.Trainee("A", "  "), "blank institute");
        expectIllegalArgument(() -> new Solution.ResidentTrainee("A", "B", null), "null workshop");
        expectIllegalArgument(() -> new Solution.ResidentTrainee("A", "B", "\t"), "blank workshop");
        expectIllegalArgument(() -> Solution.renderRoster(null), "null array");
        expectIllegalArgument(() -> Solution.renderRoster(new Solution.Member[]{member, null}), "null member");
    }

    private static void assertEquals(Object expected, Object actual, String message) {
        if (!java.util.Objects.equals(expected, actual)) {
            throw new AssertionError(message + ": expected " + expected + " but got " + actual);
        }
    }

    private static void assertTrue(boolean value, String message) {
        if (!value) throw new AssertionError(message);
    }

    private static void expectIllegalArgument(Runnable action, String message) {
        try {
            action.run();
            throw new AssertionError(message + ": expected IllegalArgumentException");
        } catch (IllegalArgumentException expected) {
            // expected
        }
    }

    private static void expectUnsupported(Runnable action, String message) {
        try {
            action.run();
            throw new AssertionError(message + ": expected UnsupportedOperationException");
        } catch (UnsupportedOperationException expected) {
            // expected
        }
    }
}

